import os from 'os';
import fs from 'fs';
import { execSync } from 'child_process';
import { A2UI, sendA2UIWidget } from '../../lib/a2ui.js';

// ===== KONSTANTA GLOBAL =====
const WIDGET_IMG = 'https://c.termai.cc/a199/0Dw0j.jpg'; // Gambar header untuk widget

// ===== FUNGSI HELPER =====

/**
 * Memformat ukuran byte menjadi format yang mudah dibaca (B, KB, MB, GB, TB).
 * @param {number} bytes - Jumlah byte.
 * @returns {string} Ukuran yang diformat.
 */
function formatSize(bytes) {
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let i = 0, v = bytes;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v.toFixed(i === 0 ? 0 : 2)} ${units[i]}`;
}

/**
 * Mengubah durasi dalam milidetik menjadi format yang mudah dibaca (hari, jam, menit, detik).
 * @param {number} ms - Durasi dalam milidetik.
 * @returns {string} Durasi yang diformat.
 */
function durasi(ms) {
  const t = Math.floor(ms / 1000);
  const d = Math.floor(t / 86400);
  const h = Math.floor((t % 86400) / 3600);
  const m = Math.floor((t % 3600) / 60);
  const s = t % 60;
  return [
    ...(d ? [`${d} hari`] : []),
    ...(h ? [`${h} jam`] : []),
    ...(m ? [`${m} menit`] : []),
    `${s} detik`,
  ].join(', ');
}

/**
 * Mendapatkan nama pengguna sistem.
 * @returns {string} Nama pengguna atau '-' jika gagal.
 */
function getUsername() {
  try {
    return os.userInfo().username;
  } catch {
    return '-';
  }
}

/**
 * Mendapatkan informasi penggunaan disk untuk partisi root (/).
 * @returns {{total: number, used: number, percent: number} | null} Objek informasi disk atau null jika gagal.
 */
function getDisk() {
  try {
    const out = execSync('df -kP /', { timeout: 3000 }).toString().trim().split('\n');
    const row = out.slice(1).map(l => l.trim().split(/\s+/))[0];
    const total = +row[1] * 1024; // df -kP memberikan dalam KB, konversi ke byte
    const used = +row[2] * 1024; // df -kP memberikan dalam KB, konversi ke byte
    return { total, used, percent: +(used / total * 100).toFixed(1) };
  } catch {
    return null;
  }
}

/**
 * Mendapatkan informasi penggunaan memori swap dari /proc/meminfo.
 * @returns {{total: number, used: number, free: number, percent: number} | null} Objek informasi swap atau null jika gagal.
 */
function getSwap() {
  try {
    const f = fs.readFileSync('/proc/meminfo', 'utf8');
    const total = ((f.match(/^SwapTotal:\s+(\d+)/) || [0, 0])[1]) * 1024; // SwapTotal dalam KB, konversi ke byte
    const free = ((f.match(/^SwapFree:\s+(\d+)/) || [0, 0])[1]) * 1024; // SwapFree dalam KB, konversi ke byte
    if (!total) return null; // Jika tidak ada swap total
    const used = total - free;
    return { total, used, free, percent: +(used / total * 100).toFixed(1) };
  } catch {
    return null;
  }
}

/**
 * Mendapatkan informasi antarmuka jaringan.
 * @returns {{list: string[], count: number, primary: string}} Objek berisi daftar antarmuka, jumlahnya, dan IP utama.
 */
function getNetwork() {
  const ni = os.networkInterfaces();
  const list = [];
  let primary = '';
  for (const [name, addrs] of Object.entries(ni)) {
    for (const a of addrs || []) {
      if (a.internal) continue; // Lewati antarmuka internal
      list.push(`${name} · ${a.address}`);
      if (!primary && a.family === 'IPv4') primary = a.address; // Ambil IP IPv4 pertama sebagai primary
    }
  }
  return {
    list: list.slice(0, 6), // Ambil 6 antarmuka teratas
    count: Object.keys(ni).filter(k => (ni[k] || []).some(a => !a.internal)).length, // Hitung antarmuka non-internal
    primary: primary || list[0]?.split(' · ')[1] || '-', // Gunakan IP primary, atau IP pertama jika tidak ada primary, atau '-'
  };
}

// ===== PEMBANGUN WIDGET (Menggunakan A2UI Builder) =====

/**
 * Membangun permukaan widget A2UI dengan informasi sistem.
 * @param {object} d - Objek berisi data sistem yang sudah diproses.
 * @returns {string} String representasi widget A2UI yang siap dikirim.
 */
function buildSurface(d) {
  const ui = new A2UI({ version: 'v0.9' }); // Inisialisasi A2UI builder

  // Bagian Hero/Header Widget
  const hero = ui.card(ui.column([
    ui.text('Server Inspector', { variant: 'h1' }),
    ui.text('Live operating system information', { variant: 'caption' }),
    ui.image(WIDGET_IMG, { variant: 'header', fit: 'cover' }), // Gambar header
    ui.text(`● ${d.botName}`), // Nama bot
  ]));

  // Bagian Informasi Sistem
  const system = ui.section('System Information', [
    `OS · ${d.osType}`,
    `Kernel · ${d.kernel}`,
    `Architecture · ${d.arch}`,
    `CPU · ${d.cpuShort}`,
    `CPU Cores · ${d.cores}`,
    `Hostname · ${d.hostname}`,
    `User · ${d.username}`,
    `Endianness · ${d.endianness}`,
  ]);

  // Bagian Sumber Daya Sistem
  const resources = ui.section('System Resources', [
    { slider: true, label: `CPU · ${d.cpuPercent}%`, value: d.cpuPercent }, // Slider CPU
    { slider: true, label: `RAM · ${d.memPercent}%`, value: d.memPercent }, // Slider RAM
    ...(d.disk ? [{ slider: true, label: `SSD Storage · ${d.disk.percent}%`, value: d.disk.percent }] : []), // Slider Disk jika ada
    {
      variant: 'caption',
      text: [
        `CPU Load · ${d.load1} · ${d.load5} · ${d.load15}`, // Load average
        `RAM · ${d.memUsed} / ${d.memTotal}`, // Penggunaan RAM
        ...(d.disk ? [`SSD · ${formatSize(d.disk.used)} / ${formatSize(d.disk.total)}`] : []), // Penggunaan Disk jika ada
      ].join('\n'),
    },
  ]);

  // Bagian Memori Node.js
  const nodeMemory = ui.section('Node.js Memory', [
    `RSS · ${d.rss}`,
    `Heap Total · ${d.heapTotal}`,
    `Heap Used · ${d.heapUsed}`,
    `External · ${d.external}`,
    `ArrayBuffers · ${d.arrayBuffers}`,
  ]);

  // Bagian Memori Swap (opsional)
  const swap = d.swap ? ui.section('Swap Memory', [
    { slider: true, label: `Swap Usage · ${d.swap.percent}%`, value: d.swap.percent }, // Slider Swap
    `Total · ${formatSize(d.swap.total)}`,
    `Used · ${formatSize(d.swap.used)}`,
    `Free · ${formatSize(d.swap.free)}`,
  ]) : null; // Jika tidak ada swap, bagian ini akan null

  // Bagian Jaringan
  const network = ui.section('Network', [
    `Primary IP · ${d.netPrimary}`,
    `Interfaces · ${d.netCount}`,
    { variant: 'caption', text: d.netList }, // Daftar antarmuka jaringan
  ]);

  // Bagian Runtime
  const runtime = ui.section('Runtime', [
    `Runtime · ${d.runtimeName}`,
    `${d.runtimeName} Version · ${d.runtimeVersion}`,
    `Node Compatibility · ${d.nodeCompat}`,
    `JavaScript Engine · ${d.engine}`,
    `PID · ${d.pid}`,
    `Bot Uptime · ${d.botUptime}`,
    `System Uptime · ${d.sysUptime}`,
    { variant: 'caption', text: `Executable · ${d.executable}` },
  ]);

  // Menggabungkan semua bagian menjadi root widget
  ui.root([hero, system, resources, nodeMemory, ...(swap ? [swap] : []), network, runtime]);

  // Membangun widget dan memberikan ID unik
  return ui.build(`ping-os=${Date.now()}`);
}

// ===== HANDLER PERINTAH =====

/**
 * Handler utama untuk perintah 'ping', 'speed', 'os'.
 * Menampilkan informasi sistem dalam bentuk widget A2UI atau teks fallback.
 * @param {object} m - Objek pesan dari bot.
 * @param {object} _0 - Objek konteks (conn, dll.).
 */
let handler = async (m, { conn }) => {
  const start = Date.now(); // Waktu mulai eksekusi handler
  await m.react('🍡'); // Reaksi bot untuk menandakan sedang memproses

  // Mengumpulkan data sistem menggunakan modul 'os' dan 'process'
  const cores = os.cpus().length;
  const load = os.loadavg(); // [load1, load5, load15]
  const totalMem = os.totalmem();
  const freeMem = os.freemem();
  const usedMem = totalMem - freeMem;
  const heap = process.memoryUsage(); // Memori Node.js
  const isBun = typeof Bun !== 'undefined'; // Cek apakah runtime adalah Bun
  const net = getNetwork(); // Mendapatkan informasi jaringan

  // Objek 'd' untuk menyimpan semua data sistem yang telah diproses
  const d = {
    botName: conn?.user?.name || String(conn?.user?.id || '').split('@')[0] || 'WhatsApp Bot', // Nama bot
    speed: Date.now() - start, // Kecepatan eksekusi handler
    osType: `${os.type()} ${os.release()}`, // Tipe OS dan rilisnya
    kernel: os.release(), // Versi kernel
    arch: os.arch(), // Arsitektur CPU
    cpuShort: (os.cpus()[0]?.model || 'Unknown').replace(/\(R\)|\(TM\)/g, '').trim(), // Model CPU (disederhanakan)
    cores, // Jumlah core CPU
    hostname: os.hostname(), // Hostname server
    username: getUsername(), // Nama pengguna sistem
    endianness: os.endianness(), // Endianness sistem
    // Estimasi persentase CPU berdasarkan load average
    cpuPercent: +Math.min(99.9, (load[0] / Math.max(cores, 1)) * 100).toFixed(1),
    load1: load[0].toFixed(2), // Load average 1 menit
    load5: load[1].toFixed(2), // Load average 5 menit
    load15: load[2].toFixed(2), // Load average 15 menit
    memPercent: +((usedMem / totalMem) * 100).toFixed(1), // Persentase penggunaan RAM
    memUsed: formatSize(usedMem), // RAM terpakai (diformat)
    memTotal: formatSize(totalMem), // Total RAM (diformat)
    rss: formatSize(heap.rss), // Resident Set Size (memori Node.js)
    heapTotal: formatSize(heap.heapTotal), // Total memori heap Node.js
    heapUsed: formatSize(heap.heapUsed), // Memori heap Node.js yang terpakai
    external: formatSize(heap.external), // Memori eksternal Node.js
    arrayBuffers: formatSize(heap.arrayBuffers ?? 0), // Memori ArrayBuffers Node.js
    disk: getDisk(), // Informasi disk
    swap: getSwap(), // Informasi swap
    netPrimary: net.primary, // IP jaringan utama
    netCount: net.count, // Jumlah antarmuka jaringan
    netList: net.list.join('\n') || '-', // Daftar antarmuka jaringan
    runtimeName: isBun ? 'Bun' : 'Node.js', // Nama runtime
    runtimeVersion: isBun ? Bun.version : process.version, // Versi runtime
    nodeCompat: `v${process.versions.node}`, // Versi Node.js yang kompatibel
    engine: isBun ? 'JavaScriptCore' : `V8 ${process.versions.v8}`, // Engine JavaScript
    pid: process.pid, // PID proses bot
    botUptime: durasi(process.uptime() * 1000), // Waktu aktif bot
    sysUptime: durasi(os.uptime() * 1000), // Waktu aktif sistem
    executable: process.execPath || '-', // Path executable Node.js/Bun
  };

  // Membangun permukaan widget A2UI
  const surface = buildSurface(d);

  // Teks fallback jika pengiriman widget gagal
  const fallbackText =
    `🔍 *PONG!* • ${d.speed}ms\n\n` +
    `💻 ${d.cpuShort} • ${d.cores} threads\n` +
    `🧠 RAM: ${d.memPercent}% (${d.memUsed} / ${d.memTotal})\n` +
    `📦 ${d.runtimeName} ${d.runtimeVersion} • Heap ${d.heapUsed}\n` +
    (d.disk ? `🗄️ Disk: ${d.disk.percent}% (${formatSize(d.disk.used)} / ${formatSize(d.disk.total)})\n` : '') +
    `⏱️ Uptime: ${d.botUptime}`;

  try {
    // Mencoba mengirim widget A2UI
    await sendA2UIWidget(conn, m.chat, { surface });
  } catch (e) {
    // Jika gagal, kirim teks fallback
    console.error('[PING A2UI ERROR
